inline const DAV *GetDAV(const void *buf) {
  return ::flatbuffers::GetRoot<DAV>(buf);
}

inline const DAV *GetSizePrefixedDAV(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<DAV>(buf);
}

inline const char *DAVIdentifier() {
  return "$DAV";
}

inline bool DAVBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, DAVIdentifier());
}

inline bool SizePrefixedDAVBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, DAVIdentifier(), true);
}

template <bool B = false>
inline bool VerifyDAVBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<DAV>(DAVIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedDAVBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<DAV>(DAVIdentifier());
}

inline void FinishDAVBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<DAV> root) {
  fbb.Finish(root, DAVIdentifier());
}

inline void FinishSizePrefixedDAVBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<DAV> root) {
  fbb.FinishSizePrefixed(root, DAVIdentifier());
}

inline std::unique_ptr<DAVT> UnPackDAV(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<DAVT>(GetDAV(buf)->UnPack(res));
}

inline std::unique_ptr<DAVT> UnPackSizePrefixedDAV(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<DAVT>(GetSizePrefixedDAV(buf)->UnPack(res));
}

